package android.preference;import android.content.Context;import java.util.*;public class PreferenceGroup extends Preference{public final List<Preference> entries=new ArrayList<>();public PreferenceGroup(Context c){super(c);}public boolean addPreference(Preference p){entries.add(p);return true;}public boolean removePreference(Preference p){return entries.remove(p);}public int getPreferenceCount(){return entries.size();}public Preference getPreference(int i){return entries.get(i);}public Preference findPreference(CharSequence key){return find(key.toString());}public Preference find(String key){for(Preference p:entries){if(key.equals(p.getKey()))return p;if(p instanceof PreferenceGroup){Preference r=((PreferenceGroup)p).find(key);if(r!=null)return r;}}return null;}}
